style.css:
/* --- Background Image --- */
body {
    background: url("https://i.imgur.com/YJmFvJy.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    overflow: hidden !important;
}

/* --- Falling Leaves Animation (CSS-only) --- */
@keyframes fall {
    0% {
        transform: translateY(-10vh) translateX(0) rotate(0deg);
        opacity: 0;
    }
    20% {
        opacity: 1;
    }
    100% {
        transform: translateY(110vh) translateX(20vw) rotate(360deg);
        opacity: 0;
    }
}

/* Create multiple leaves via pseudo-elements */
body::before,
body::after {
    content: "";
    position: fixed;
    top: -10vh;
    width: 40px;
    height: 40px;
    background-image: url("https://i.imgur.com/kA7H0gH.png");
    background-size: contain;
    background-repeat: no-repeat;
    pointer-events: none;
    z-index: 999999;
    animation: fall linear infinite;
}

/* Leaf #1 */
body::before {
    left: 20%;
    animation-duration: 8s;
}

/* Leaf #2 */
body::after {
    left: 70%;
    animation-duration: 11s;
}

/* Extra fake leaves created using drop-shadow to multiply them */

body {
    filter: drop-shadow(0 0 0 transparent); /* required for clones */
}

@keyframes fall2 {
    0% {
        transform: translateY(-15vh) translateX(-10vw) rotate(0deg);
        opacity: 0;
    }
    20% {
        opacity: 1;
    }
    100% {
        transform: translateY(120vh) translateX(10vw) rotate(-360deg);
        opacity: 0;
    }
}

body::after {
    filter: drop-shadow(50px 0px 0px rgba(255, 165, 0, 0.8))
            drop-shadow(-60px 20px 0px rgba(255, 69, 0, 0.8))
            drop-shadow(30px -20px 0px rgba(255, 140, 0, 0.8));
    animation-name: fall2;
}
